"ssb": ["select\n    sum(lo_extendedprice * lo_discount) as revenue\nfrom\n    lineorder,\n    date\nwhere\n    lo_orderdate = d_datekey\n    and d_year = 1993\n    and lo_discount between 1 and 3\n    and lo_quantity < 25;", "select\n    sum(lo_extendedprice * lo_discount) as revenue\nfrom\n    lineorder,\n    date\nwhere\n    lo_orderdate = d_datekey\n    and d_yearmonthnum = 199401\n    and lo_discount between 4 and 6\n    and lo_quantity between 26 and 35;", "select\n    sum(lo_extendedprice * lo_discount) as revenue\nfrom\n    lineorder,\n    date\nwhere\n    lo_orderdate = d_datekey\n    and d_weeknuminyear = 6\n    and d_year = 1994\n    and lo_discount between 5 and 7\n    and lo_quantity between 26 and 35;", "select\n    sum(lo_revenue),\n    d_year,\n    p_brand1\nfrom\n    lineorder,\n    date,\n    part,\n    supplier\nwhere\n    lo_orderdate = d_datekey\n    and lo_partkey = p_partkey\n    and lo_suppkey = s_suppkey\n    and p_category = 'MFGR#12'\n    and s_region = 'AMERICA'\ngroup by\n    d_year,\n    p_brand1\norder by\n    d_year,\n    p_brand1;", "select\n    sum(lo_revenue),\n    d_year,\n    p_brand1\nfrom\n    lineorder,\n    date,\n    part,\n    supplier\nwhere\n    lo_orderdate = d_datekey\n    and lo_partkey = p_partkey\n    and lo_suppkey = s_suppkey\n    and p_brand1 between 'MFGR#2221' and 'MFGR#2228'\n    and s_region = 'ASIA'\ngroup by\n    d_year,\n    p_brand1\norder by\n    d_year,\n    p_brand1;", "select\n    sum(lo_revenue),\n    d_year,\n    p_brand1\nfrom\n    lineorder,\n    date,\n    part,\n    supplier\nwhere\n    lo_orderdate = d_datekey\n    and lo_partkey = p_partkey\n    and lo_suppkey = s_suppkey\n    and p_brand1 = 'MFGR#2239'\n    and s_region = 'EUROPE'\ngroup by\n    d_year,\n    p_brand1\norder by\n    d_year,\n    p_brand1;", "select\n    c_nation,\n    s_nation,\n    d_year,\n    sum(lo_revenue) as revenue\nfrom\n    customer,\n    lineorder,\n    supplier,\n    date\nwhere\n    lo_custkey = c_custkey\n    and lo_suppkey = s_suppkey\n    and lo_orderdate = d_datekey\n    and c_region = 'ASIA'\n    and s_region = 'ASIA'\n    and d_year >= 1992\n    and d_year <= 1997\ngroup by\n    c_nation,\n    s_nation,\n    d_year\norder by\n    d_year asc,\n    revenue desc,\n    c_nation,\n    s_nation;", "select\n    c_city,\n    s_city,\n    d_year,\n    sum(lo_revenue) as revenue\nfrom\n    customer,\n    lineorder,\n    supplier,\n    date\nwhere\n    lo_custkey = c_custkey\n    and lo_suppkey = s_suppkey\n    and lo_orderdate = d_datekey\n    and c_nation = 'UNITED STATES'\n    and s_nation = 'UNITED STATES'\n    and d_year >= 1992\n    and d_year <= 1997\ngroup by\n    c_city,\n    s_city,\n    d_year\norder by\n    d_year asc,\n    revenue desc,\n    c_city,\n    s_city;", "select\n    c_city,\n    s_city,\n    d_year,\n    sum(lo_revenue) as revenue\nfrom\n    customer,\n    lineorder,\n    supplier,\n    date\nwhere\n    lo_custkey = c_custkey\n    and lo_suppkey = s_suppkey\n    and lo_orderdate = d_datekey\n    and (c_city = 'UNITED KI1' or c_city = 'UNITED KI5')\n    and (s_city = 'UNITED KI1' or s_city = 'UNITED KI5')\n    and d_year >= 1992\n    and d_year <= 1997\ngroup by\n    c_city,\n    s_city,\n    d_year\norder by\n    d_year asc,\n    revenue desc,\n    c_city,\n    s_city;", "select\n    c_city,\n    s_city,\n    d_year,\n    sum(lo_revenue) as revenue\nfrom\n    customer,\n    lineorder,\n    supplier,\n    date\nwhere\n    lo_custkey = c_custkey\n    and lo_suppkey = s_suppkey\n    and lo_orderdate = d_datekey\n    and (c_city = 'UNITED KI1' or c_city = 'UNITED KI5')\n    and (s_city = 'UNITED KI1' or s_city = 'UNITED KI5')\n    and d_yearmonth = 'Dec1997'\ngroup by\n    c_city,\n    s_city,\n    d_year\norder by\n    d_year asc,\n    revenue desc,\n    c_city,\n    s_city;", "select\n    d_year,\n    c_nation,\n    sum(lo_revenue - lo_supplycost) as profit\nfrom\n    date,\n    customer,\n    supplier,\n    part,\n    lineorder\nwhere\n    lo_custkey = c_custkey\n    and lo_suppkey = s_suppkey\n    and lo_partkey = p_partkey\n    and lo_orderdate = d_datekey\n    and c_region = 'AMERICA'\n    and s_region = 'AMERICA'\n    and (p_mfgr = 'MFGR#1' or p_mfgr = 'MFGR#2')\ngroup by\n    d_year,\n    c_nation\norder by\n    d_year,\n    c_nation;", "select\n    d_year,\n    s_nation,\n    p_category,\n    sum(lo_revenue - lo_supplycost) as profit\nfrom\n    date,\n    customer,\n    supplier,\n    part,\n    lineorder\nwhere\n    lo_custkey = c_custkey\n    and lo_suppkey = s_suppkey\n    and lo_partkey = p_partkey\n    and lo_orderdate = d_datekey\n    and c_region = 'AMERICA'\n    and s_region = 'AMERICA'\n    and (d_year = 1997 or d_year = 1998)\n    and (p_mfgr = 'MFGR#1' or p_mfgr = 'MFGR#2')\ngroup by\n    d_year,\n    s_nation,\n    p_category\norder by\n    d_year,\n    s_nation,\n    p_category;", "select\n    d_year,\n    s_city,\n    p_brand1,\n    sum(lo_revenue - lo_supplycost) as profit\nfrom\n    date,\n    customer,\n    supplier,\n    part,\n    lineorder\nwhere\n    lo_custkey = c_custkey\n    and lo_suppkey = s_suppkey\n    and lo_partkey = p_partkey\n    and lo_orderdate = d_datekey\n    and c_region = 'AMERICA'\n    and s_nation = 'UNITED STATES'\n    and (d_year = 1997 or d_year = 1998)\n    and p_category = 'MFGR#14'\ngroup by\n    d_year,\n    s_city,\n    p_brand1\norder by\n    d_year,\n    s_city,\n    p_brand1;"],
